def semver_sort(versions):
    def parse_key(v):
        main = v.split('+', 1)[0]
        if '-' in main:
            core, prerelease = main.split('-', 1)
        else:
            core, prerelease = main, None

        major, minor, patch = (int(x) for x in core.split('.'))

        if prerelease is None:
            return (major, minor, patch, 1, ())
        else:
            idents = prerelease.split('.')
            key_idents = []
            for ident in idents:
                if ident.isdigit():
                    key_idents.append((0, int(ident), ''))
                else:
                    key_idents.append((1, 0, ident))
            return (major, minor, patch, 0, tuple(key_idents))

    return sorted(versions, key=parse_key)

